class CartManager {
    constructor() {
        this.items = [];
        this.cartCount = document.querySelector('.cart-count');
        this.notification = document.getElementById('cart-notification');
        this.notificationMessage = document.getElementById('notification-message');
    }

    addItem(productName) {
        this.items.push(productName);
        this.updateCartCount();
        this.showNotification(`${productName} added to cart`);
    }

    updateCartCount() {
        this.cartCount.textContent = this.items.length;
    }

    showNotification(message) {
        this.notificationMessage.textContent = message;
        this.notification.classList.add('show');

        setTimeout(() => {
            this.notification.classList.remove('show');
        }, 3000);
    }
}

class SearchToggle {
    constructor() {
        this.searchToggle = document.querySelector('.search-toggle');
        this.searchBox = document.getElementById('search-box');
        this.searchInput = this.searchBox.querySelector('input');
        this.searchCloseBtn = this.searchBox.querySelector('button');

        this.setupEventListeners();
    }

    setupEventListeners() {
        this.searchToggle.addEventListener('click', () => this.toggleSearch());
        this.searchCloseBtn.addEventListener('click', () => this.closeSearch());

        // Close on Escape key
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && !this.searchBox.hidden) {
                this.closeSearch();
            }
        });
    }

    toggleSearch() {
        const isOpen = !this.searchBox.hidden;
        if (isOpen) {
            this.closeSearch();
        } else {
            this.openSearch();
        }
    }

    openSearch() {
        this.searchBox.hidden = false;
        this.searchToggle.setAttribute('aria-expanded', 'true');
        this.searchInput.focus();
    }

    closeSearch() {
        this.searchBox.hidden = true;
        this.searchToggle.setAttribute('aria-expanded', 'false');
        this.searchToggle.focus();
    }
}

class ProductList {
    constructor(cartManager) {
        this.cartManager = cartManager;
        this.addToCartButtons = document.querySelectorAll('.add-to-cart-btn');
        this.setupEventListeners();
    }

    setupEventListeners() {
        this.addToCartButtons.forEach(button => {
            button.addEventListener('click', (e) => {
                const productName = button.getAttribute('data-product');
                this.cartManager.addItem(productName);
            });
        });
    }
}

class NewsletterForm {
    constructor() {
        this.form = document.querySelector('.newsletter-form');
        this.emailInput = this.form.querySelector('input[type="email"]');
        this.submitButton = this.form.querySelector('button[type="submit"]');

        this.setupEventListeners();
    }

    setupEventListeners() {
        this.form.addEventListener('submit', (e) => {
            e.preventDefault();
            this.handleSubmit();
        });
    }

    handleSubmit() {
        const email = this.emailInput.value;

        if (!this.validateEmail(email)) {
            this.emailInput.setAttribute('aria-invalid', 'true');
            return;
        }

        this.emailInput.setAttribute('aria-invalid', 'false');

        // Simulate subscription
        const originalText = this.submitButton.textContent;
        this.submitButton.textContent = 'Subscribed!';
        this.submitButton.disabled = true;

        setTimeout(() => {
            this.emailInput.value = '';
            this.submitButton.textContent = originalText;
            this.submitButton.disabled = false;
        }, 2000);
    }

    validateEmail(email) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }
}

class Navigation {
    constructor() {
        this.navMenu = document.querySelector('.nav-menu');
        this.navLinks = this.navMenu.querySelectorAll('a');
        this.setupEventListeners();
    }

    setupEventListeners() {
        this.navLinks.forEach(link => {
            link.addEventListener('click', () => {
                this.closeMenu();
            });
        });
    }

    closeMenu() {
        this.navMenu.classList.remove('active');
    }
}

